import React, { useEffect, useState } from "react";

const formatRdvTask = value => {
  if (!value) return "RDV";
  const [h, m] = String(value).split(":");
  return `RDV • ${String(h || "").padStart(2, "0")}h${String(m || "00").padStart(2, "0")}`;
};

const emptyDays = () => ({ lundi:false, mardi:false, mercredi:false, jeudi:false, vendredi:false });

const daysFromSelectedDate = selectedDate => {
  const result = emptyDays();
  if (!selectedDate) return result;
  const date = new Date(selectedDate);
  if (Number.isNaN(date.getTime())) return result;
  const keyByDow = { 1:"lundi", 2:"mardi", 3:"mercredi", 4:"jeudi", 5:"vendredi" };
  const key = keyByDow[date.getDay()];
  if (key) result[key] = true;
  return result;
};

const selectedDateLabel = selectedDate => {
  if (!selectedDate) return "";
  const date = new Date(selectedDate);
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleDateString("fr-FR", { weekday:"long", day:"numeric", month:"long", year:"numeric" });
};

export const FormAffectation = ({ ouvrier, chantiers, onSubmit, onCancel, selectedDate = null }) => {
  const chantiersActifs = chantiers
    .filter(c => c.statut === "Actif")
    .sort((a, b) => String(a.nom || "").localeCompare(String(b.nom || ""), "fr", { sensitivity: "base" }));
  const normalizeChantierName = value => String(value || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").trim().toUpperCase();
  const shortChantierId = id => String(id ?? "").replace(/\s+/g, "").slice(-4).toUpperCase() || "?";
  const homonymCounts = new Map();
  chantiersActifs.forEach(c => {
    const key = normalizeChantierName(c.nom);
    homonymCounts.set(key, (homonymCounts.get(key) || 0) + 1);
  });
  const chantierLabel = c => homonymCounts.get(normalizeChantierName(c.nom)) > 1
    ? `${c.nom} · #${shortChantierId(c.id)}`
    : c.nom;

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [notice, setNotice] = useState(null);
  const [mode, setMode] = useState("chantier");
  const [days, setDays] = useState(() => daysFromSelectedDate(selectedDate));
  const [preciseDate, setPreciseDate] = useState("");
  const [formData, setFormData] = useState({ chantierId:"", nomLibre:"", tache:"", rdvHeure:"" });
  const compactLandscape = typeof window !== "undefined" && window.matchMedia("(max-width: 1100px) and (orientation: landscape)").matches;
  const affectationsLibres = [
    "Congé",
    "Arrêt maladie",
    "Accident du travail",
    "Congé parental",
    "Formation",
    "Récup",
    "Congé sans solde",
    "Absence autorisée",
    "Absent"
  ];

  useEffect(() => {
    setDays(daysFromSelectedDate(selectedDate));
    setPreciseDate("");
  }, [selectedDate]);

  const parsePreciseDate = value => {
    if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
    const [year, month, day] = value.split("-").map(Number);
    const date = new Date(year, month - 1, day);
    if (
      Number.isNaN(date.getTime()) ||
      date.getFullYear() !== year ||
      date.getMonth() !== month - 1 ||
      date.getDate() !== day
    ) return null;
    date.setHours(0,0,0,0);
    return date;
  };

  const formatApiDate = date =>
    `${String(date.getDate()).padStart(2,"0")}/${String(date.getMonth()+1).padStart(2,"0")}/${date.getFullYear()}`;

  const getDateRange = ({ showNotice = true } = {}) => {
    if (preciseDate) {
      const exactDate = parsePreciseDate(preciseDate);
      if (!exactDate) {
        if (showNotice) setNotice({ title:"Date invalide", message:"Choisissez une date précise valide." });
        return null;
      }
      const dow = exactDate.getDay();
      if (dow === 0 || dow === 6) {
        if (showNotice) setNotice({ title:"Jour non affiché", message:"AB Planning affiche les affectations du lundi au vendredi. Choisissez un jour ouvré." });
        return null;
      }
      const formatted = formatApiDate(exactDate);
      return {
        dateDebut: formatted,
        dateFin: formatted,
        preview: `Date retenue : ${selectedDateLabel(exactDate)}`
      };
    }

    const order = ["lundi","mardi","mercredi","jeudi","vendredi"];
    const checked = order.filter(d => days[d]);
    if (!checked.length) {
      if (showNotice) setNotice({ title:"Jour manquant", message:"Sélectionnez au moins un jour dans la semaine ou choisissez une date précise." });
      return null;
    }
    const clicked = selectedDate ? new Date(selectedDate) : new Date();
    clicked.setHours(0,0,0,0);
    const dow = clicked.getDay();
    const monday = new Date(clicked);
    monday.setDate(monday.getDate() - (dow === 0 ? 6 : dow - 1));
    const indexes = checked.map(d => order.indexOf(d));
    const debut = new Date(monday);
    const fin = new Date(monday);
    debut.setDate(debut.getDate() + Math.min(...indexes));
    fin.setDate(fin.getDate() + Math.max(...indexes));
    const dateDebut = formatApiDate(debut);
    const dateFin = formatApiDate(fin);
    return {
      dateDebut,
      dateFin,
      preview: debut.getTime() === fin.getTime()
        ? `Date retenue : ${selectedDateLabel(debut)}`
        : `Période retenue : ${selectedDateLabel(debut)} → ${selectedDateLabel(fin)}`
    };
  };

  const selectedRangePreview = getDateRange({ showNotice:false });


  const handleSubmit = async e => {
    e.preventDefault();
    if (isSubmitting) return;

    if (mode === "chantier" && !formData.chantierId) {
      setNotice({ title:"Chantier manquant", message:"Choisissez le chantier à planifier." });
      return;
    }
    if (mode === "libre" && !formData.nomLibre.trim()) {
      setNotice({ title:"Affectation manquante", message:"Choisissez ou écrivez une affectation libre." });
      return;
    }
    if (mode === "rdv" && !formData.nomLibre.trim()) {
      setNotice({ title:"Nom manquant", message:"Donnez un nom à l’affectation." });
      return;
    }
    if (mode === "rdv" && !formData.rdvHeure) {
      setNotice({ title:"Heure manquante", message:"Indiquez l’heure du rendez-vous." });
      return;
    }

    const range = getDateRange();
    if (!range) return;

    setIsSubmitting(true);
    const tache = mode === "rdv" ? formatRdvTask(formData.rdvHeure) : formData.tache.trim();

    await onSubmit({
      chantierId: mode === "chantier" ? formData.chantierId : `__LIBRE__:${formData.nomLibre.trim()}`,
      dateDebut: range.dateDebut,
      dateFin: range.dateFin,
      tache
    });
    setIsSubmitting(false);
  };

  const label = {
    fontSize: compactLandscape ? 10 : 11,
    fontWeight: 700,
    color:"#374151",
    display:"block",
    marginBottom: compactLandscape ? 3 : 5
  };
  const input = {
    width:"100%",
    padding:compactLandscape ? "6px 8px" : "9px 10px",
    borderRadius:6,
    border:"1px solid #d1d5db",
    fontSize:12,
    fontFamily:"inherit",
    boxSizing:"border-box"
  };
  const dayList = [
    {key:"lundi",label:"Lun"},
    {key:"mardi",label:"Mar"},
    {key:"mercredi",label:"Mer"},
    {key:"jeudi",label:"Jeu"},
    {key:"vendredi",label:"Ven"}
  ];

  const modeButton = (key, color, background) => ({
    padding:compactLandscape ? 7 : 10,
    borderRadius:7,
    border:mode === key ? `2px solid ${color}` : "1px solid #d1d5db",
    background:mode === key ? background : "white",
    color,
    fontWeight:700,
    cursor:"pointer",
    fontSize:compactLandscape ? 11 : 13
  });

  return (
    <>
      <form onSubmit={handleSubmit} style={{display:"flex",flexDirection:"column",gap:compactLandscape ? 8 : 14}}>
        <div>
          <label style={label}>Ouvrier</label>
          <div style={{padding:compactLandscape ? "6px 8px" : "9px 10px",background:"#f3f4f6",borderRadius:6,border:"1px solid #e5e7eb",fontSize:12,fontWeight:700}}>
            {ouvrier.nom}
          </div>
        </div>

        <div>
          <label style={label}>Type d’affectation</label>
          <div style={{display:"grid",gridTemplateColumns:"repeat(3, 1fr)",gap:6}}>
            <button type="button" onClick={()=>setMode("chantier")} style={modeButton("chantier","#1e3a8a","#eff6ff")}>🏗️ Chantier</button>
            <button type="button" onClick={()=>setMode("libre")} style={modeButton("libre","#374151","#f3f4f6")}>📝 Libre</button>
            <button type="button" onClick={()=>setMode("rdv")} style={modeButton("rdv","#6d28d9","#f5f3ff")}>📅 RDV</button>
          </div>
        </div>

        {mode === "chantier" ? (
          <div>
            <label style={label}>Chantier *</label>
            <select value={formData.chantierId} onChange={e=>setFormData({...formData,chantierId:e.target.value})} style={input}>
              <option value="">-- Sélectionner --</option>
              {chantiersActifs.map(c=><option key={c.id} value={c.id}>{chantierLabel(c)}</option>)}
            </select>
          </div>
        ) : (
          <div>
            <label style={label}>{mode === "rdv" ? "Nom du rendez-vous *" : "Affectation libre *"}</label>
            <input
              value={formData.nomLibre}
              onChange={e=>setFormData({...formData,nomLibre:e.target.value})}
              placeholder={mode === "rdv" ? "Ex : HERVOUET" : "Ex : congé, arrêt maladie, congé parental…"}
              style={{...input,border:mode === "rdv" ? "2px solid #7c3aed" : "2px solid #9ca3af"}}
            />
            {mode === "libre" && (
              <div style={{display:"flex",gap:5,flexWrap:"wrap",marginTop:7}}>
                {affectationsLibres.map(item => (
                  <button
                    key={item}
                    type="button"
                    onClick={()=>setFormData({...formData,nomLibre:item})}
                    style={{
                      border:formData.nomLibre === item ? "2px solid #374151" : "1px solid #d1d5db",
                      background:formData.nomLibre === item ? "#f3f4f6" : "white",
                      borderRadius:999,
                      padding:compactLandscape ? "3px 7px" : "5px 9px",
                      fontSize:10,
                      fontWeight:700,
                      color:"#374151",
                      cursor:"pointer"
                    }}
                  >
                    {item}
                  </button>
                ))}
              </div>
            )}
          </div>
        )}

        <div>
          <label style={label}>Jours de la semaine *</label>
          {selectedDateLabel(selectedDate) && (
            <div style={{marginBottom:6,fontSize:10,fontWeight:800,color:"#1e3a8a",background:"#eff6ff",border:"1px solid #bfdbfe",borderRadius:6,padding:"5px 7px"}}>
              Jour cliqué : {selectedDateLabel(selectedDate)} — présélectionné automatiquement
            </div>
          )}
          <div style={{display:"flex",gap:6}}>
            {dayList.map(day=>(
              <button
                key={day.key}
                type="button"
                onClick={()=>setDays(p=>({...p,[day.key]:!p[day.key]}))}
                disabled={Boolean(preciseDate)}
                style={{
                  flex:1,
                  padding:compactLandscape ? "6px 3px" : "9px 4px",
                  borderRadius:6,
                  border:days[day.key] ? "2px solid #1e3a8a" : "1px solid #d1d5db",
                  background:days[day.key] ? "#1e3a8a" : "white",
                  color:days[day.key] ? "white" : "#374151",
                  fontSize:11,
                  fontWeight:700,
                  cursor:preciseDate ? "not-allowed" : "pointer",
                  opacity:preciseDate ? 0.5 : 1
                }}
              >
                {day.label}
              </button>
            ))}
          </div>

          <div style={{marginTop:compactLandscape ? 7 : 10,padding:compactLandscape ? 7 : 9,border:"1px solid #bfdbfe",borderRadius:7,background:"#f8fbff"}}>
            <label style={{...label,color:"#1e3a8a"}}>Date précise (facultatif)</label>
            <div style={{display:"flex",gap:6,alignItems:"center"}}>
              <input
                type="date"
                value={preciseDate}
                onChange={e=>setPreciseDate(e.target.value)}
                style={{...input,flex:1,fontSize:16,minHeight:40,border:"2px solid #93c5fd",background:"white"}}
              />
              {preciseDate && (
                <button
                  type="button"
                  onClick={()=>setPreciseDate("")}
                  style={{minHeight:40,padding:"0 10px",border:"1px solid #cbd5e1",borderRadius:6,background:"white",fontSize:11,fontWeight:700,color:"#475569",cursor:"pointer"}}
                >
                  Effacer
                </button>
              )}
            </div>
            <div style={{fontSize:10,color:"#64748b",marginTop:5,lineHeight:1.3}}>
              Si une date est renseignée ici, elle est prioritaire sur les boutons Lun–Ven et crée une affectation uniquement ce jour-là.
            </div>
          </div>

          {selectedRangePreview && (
            <div style={{marginTop:7,fontSize:11,fontWeight:800,color:"#065f46",background:"#ecfdf5",border:"1px solid #a7f3d0",borderRadius:6,padding:"6px 8px"}}>
              {selectedRangePreview.preview}
            </div>
          )}
        </div>

        {mode === "rdv" ? (
          <div>
            <label style={{...label,color:"#6d28d9"}}>Heure du RDV *</label>
            <input
              type="time"
              value={formData.rdvHeure}
              onChange={e=>setFormData({...formData,rdvHeure:e.target.value})}
              style={{...input,border:"2px solid #7c3aed",background:"#faf5ff"}}
            />
            <div style={{fontSize:10,color:"#6d28d9",marginTop:4}}>
              Affichage planning : {formatRdvTask(formData.rdvHeure)}
            </div>
          </div>
        ) : (
          <div>
            <label style={label}>Tâche / description</label>
            <textarea
              rows={compactLandscape ? 1 : 2}
              value={formData.tache}
              onChange={e=>setFormData({...formData,tache:e.target.value})}
              placeholder={mode === "libre" ? "Facultatif" : "Ex : peinture chambre, reprise plafond, formation habilitation…"}
              style={{...input,resize:"vertical"}}
            />
          </div>
        )}



        <div style={{display:"flex",gap:8,marginTop:compactLandscape ? 0 : 4}}>
          <button type="submit" disabled={isSubmitting} style={{flex:1,padding:compactLandscape ? 8 : 10,background:isSubmitting ? "#9ca3af" : "#1e3a8a",color:"white",border:0,borderRadius:7,fontWeight:700,cursor:"pointer"}}>
            {isSubmitting ? "Enregistrement..." : "Ajouter"}
          </button>
          <button type="button" onClick={onCancel} disabled={isSubmitting} style={{flex:1,padding:compactLandscape ? 8 : 10,background:"#e5e7eb",color:"#374151",border:0,borderRadius:7,fontWeight:700,cursor:"pointer"}}>
            Annuler
          </button>
        </div>
      </form>

      {notice && (
        <div onClick={()=>setNotice(null)} style={{position:"fixed",inset:0,zIndex:9999,background:"rgba(15,23,42,.45)",backdropFilter:"blur(2px)",display:"flex",alignItems:"center",justifyContent:"center",padding:20}}>
          <div onClick={e=>e.stopPropagation()} style={{width:"min(420px,92vw)",background:"white",borderRadius:14,boxShadow:"0 24px 70px rgba(15,23,42,.28)",padding:20}}>
            <div style={{fontSize:15,fontWeight:800}}>{notice.title}</div>
            <div style={{marginTop:6,fontSize:12,color:"#6b7280"}}>{notice.message}</div>
            <div style={{display:"flex",justifyContent:"flex-end",marginTop:16}}>
              <button type="button" onClick={()=>setNotice(null)} style={{padding:"9px 16px",borderRadius:8,border:0,background:"#1e3a8a",color:"white",fontWeight:700,cursor:"pointer"}}>
                Compris
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};
